      heroGradient: 'radial-gradient(120% 90% at 50% -10%, rgba(168,85,247,0.24) 0%, rgba(217,70,239,0.10) 35%, rgba(10,7,18,0) 70%)',
      ctaGradient: 'linear-gradient(135deg,#a855f7,#d946ef,#f472b6)',
